namespace CardGame.Core;
[ProgramRuntimeModule,ProgramCapability]
internal sealed class MouXunYuAnniversaryRuntime(IMouXunYuAnniversaryFacts facts,IMouXunYuAnniversaryNative native,IProgramRuntimeFrames frames,IProgramRuntimeEvents events,IProgramRuntimePrompts prompts,IProgramOperationDraws draws):IMouXunYuAnniversaryRuntime
