 internal const string Shimou="mou:shimou",Bizuo="mou:bizuo";
 private static CardConversionSource Source(ProgramSkillFrame f)=>new(f.SkillId,f.TriggerId??f.ActivationId,f.OwnerSeat,f.SkillInstanceId);
 internal bool BizuoQualified()=>facts.Alive(0)&&facts.Living().All(s=>facts.Hp(0)<=facts.Hp(s));
 [ProgramTriggerLegality(ProgramTriggerLegalityPhase.BeforeGainQualification,37200,SkillProgramEffectOp.ResolveMouXunYuAnniversaryBizuo)]private bool Offer(ProgramTriggerLegalityContext c)=>BizuoQualified()&&!facts.History<MouXyBizuoGrantedEvent>().Any(e=>e.Grant.Source.OwnerSeat==c.OwnerSeat);
 [ProgramTriggerLegality(ProgramTriggerLegalityPhase.BeforeGainQualification,37203,SkillProgramEffectOp.SettleMouXunYuAnniversaryBizuo)]private bool AllocationOffer(ProgramTriggerLegalityContext c)=>facts.AllocationDue(c.OwnerSeat);
 private IReadOnlyList<int> Actors(bool yin){var all=facts.Living();if(all.Count==0)return[];var count=yin?all.Max(facts.HandCount):all.Min(facts.HandCount);return Array.AsReadOnly(all.Where(s=>facts.HandCount(s)==count).ToArray());}
 public SkillProgramStepOutcome Resolve(ProgramSkillFrame supplied,SkillProgramEffectOp op)
 {
  var f=frames.ActiveProgram(supplied.Id);if(f.MouXunYuAnniversary is not null){Continue(f.Id);return SkillProgramStepOutcome.AwaitChild;}
  if(f.InstructionIndex!=1||f.SelectedCardIds.Count!=0||f.SelectedTargetSeats.Count!=0||!facts.Parent(f))throw new InvalidOperationException("Mou Xun Yu requires his actual activation or turn boundary.");
  var lease=op==SkillProgramEffectOp.SettleMouXunYuAnniversaryBizuo?facts.AllocationLease(f)??throw new InvalidOperationException("Bizuo allocation lost its exact native extra-turn lease."):null;
  var r=new MouXyReceipt(Source(f),f.GameplayHash,op,facts.Turn){Before=facts.Sequence,After=facts.Sequence,Yin=(op is SkillProgramEffectOp.InitializeMouXunYuAnniversaryShimou or SkillProgramEffectOp.ResolveMouXunYuAnniversaryShimou)&&facts.Yin(f.OwnerSeat,facts.Instance(f.OwnerSeat,Shimou)),Lease=lease,Stage=op==SkillProgramEffectOp.InitializeMouXunYuAnniversaryShimou?MouXyStage.Initial:op==SkillProgramEffectOp.ResolveMouXunYuAnniversaryShimou?MouXyStage.Target:lease is not null?MouXyStage.Allocation:MouXyStage.Beneficiary};frames.ReplaceTop(f=f with{MouXunYuAnniversary=r});events.AdvanceFact(new MouXyStartedEvent(f.Id,r.Source,r.GameplayHash,op,r.Turn));Publish(f);return SkillProgramStepOutcome.AwaitChoice;
 }
 internal bool Valid(ProgramSkillFrame f)=>f.MouXunYuAnniversary is{}r&&r.Source==Source(f)&&r.GameplayHash==f.GameplayHash&&facts.Program(f.SkillId)?.GameplayHash==f.GameplayHash&&r.Turn==facts.Turn&&f.InstructionIndex==1&&r.Before<=r.After&&r.After<=facts.Sequence&&facts.Parent(f)&&facts.History<MouXyStartedEvent>().Count(e=>e.FrameId==f.Id&&e.Source==r.Source&&e.GameplayHash==r.GameplayHash&&e.Operation==r.Operation&&e.Turn==r.Turn)==1;
 private static PromptChoice Choice(ProgramSkillFrame f,string branch,string label,int value=-1,int? card=null,IReadOnlyList<int>? targets=null)=>new(new($"mou-xy-anniversary.{f.Id}.{f.MouXunYuAnniversary!.Stage}.{branch}.{value}.{card}.{string.Join('-',targets??[])}"),label,card is{}id?[id]:[],targets??[],new Dictionary<string,string>{{"program-action","mou-xy-anniversary"},{"branch",branch},{"value",value.ToString(CultureInfo.InvariantCulture)}});
 private IReadOnlyList<PromptChoice> Choices(ProgramSkillFrame f)
 {
  var r=f.MouXunYuAnniversary!;if(r.Stage==MouXyStage.Initial)return[Choice(f,"yang","以阳状态开始"),Choice(f,"yin","以阴状态开始")];
  if(r.Stage==MouXyStage.Target)return Array.AsReadOnly(Actors(r.Yin).Select(s=>Choice(f,"actor","令"+facts.Name(s)+"调整手牌并使用锦囊",s,targets:[s])).ToArray());
  if(r.Stage==MouXyStage.Beneficiary)return Array.AsReadOnly(facts.Living().Select(s=>Choice(f,"beneficiary","令"+facts.Name(s)+"执行额外回合",s,targets:[s])).ToArray());
  if(r.Stage==MouXyStage.Allocation)return r.AllocationCard is null?Array.AsReadOnly(facts.AllocationCards(f).Select(c=>Choice(f,"allocate-card","分配【"+c.Label+"】",card:c.Id)).ToArray()):Array.AsReadOnly(facts.Living().Select(s=>Choice(f,"allocate-recipient","将【"+r.AllocationCard.Label+"】交给"+facts.Name(s),s,targets:[s])).ToArray());
  if(r.Stage==MouXyStage.Discard){var choices=facts.Hand(r.Actor).Where(c=>!r.Selected.Contains(c.Id)).Select(c=>Choice(f,"add","弃置【"+c.Label+"】",card:c.Id)).ToList();if(r.Selected.Count>0)choices.Add(Choice(f,"clear","重选"));if(r.Selected.Count==r.Requested)choices.Add(Choice(f,"done","确认弃置"));return choices.AsReadOnly();}
  if(r.Stage==MouXyStage.Kind)return Array.AsReadOnly(facts.Plans(f).Select(p=>p.Kind).Distinct().Select(k=>Choice(f,"kind","视为使用【"+CardCatalog.Get(k).DisplayName+"】",(int)k)).ToArray());
  if(r.Stage==MouXyStage.Plan)return Array.AsReadOnly(facts.Plans(f).Where(p=>p.Kind==r.Kind).Select((p,i)=>Choice(f,"plan",(p.Extra?"增加一名目标：":"指定目标：")+string.Join('、',p.Targets.Select(facts.Name)),i,targets:p.Targets)).ToArray());
  if(r.Stage==MouXyStage.Repeat)return[Choice(f,"repeat","令此锦囊额外结算一次"),Choice(f,"single","正常结算")];return[];
 }
 private int Chooser(ProgramSkillFrame f)=>f.MouXunYuAnniversary!.Stage==MouXyStage.Discard?f.MouXunYuAnniversary.Actor:f.OwnerSeat;
 private void Publish(ProgramSkillFrame f){var choices=Choices(f);if(choices.Count==0||!facts.Alive(Chooser(f))){Finish(f);return;}var s=Chooser(f);frames.ReplaceTop(f with{Step=ResolutionFrameStep.AwaitingResponse});prompts.Set(new PendingDecision(DecisionKind.ProgramTrigger,s,"【"+facts.Presentation(f.SkillId).Name+"】请选择。",choices.SelectMany(c=>c.Cards).Distinct().ToArray(),choices.SelectMany(c=>c.Targets).Distinct().ToArray(),f.OwnerSeat){PromptId=prompts.NextId(),IsPrivate=f.MouXunYuAnniversary!.Stage==MouXyStage.Discard,Choices=choices,SkillPrompt=facts.Presentation(f.SkillId)},facts.Human(s));native.Publish();}
 [ProgramAnswer("mou-xy-anniversary")]private void Answer(PromptChoice choice)
 {
  if(frames.Top is not ProgramSkillFrame{MouXunYuAnniversary:{}r}f||!Valid(f)||prompts.Current?.PlayerSeat!=Chooser(f)||!Choices(f).Any(c=>facts.SameChoice(c,choice)))throw new InvalidOperationException("Mou Xun Yu requires the published chooser and exact current native choice.");var value=int.Parse(choice.Parameters["value"],CultureInfo.InvariantCulture);prompts.Clear();frames.ReplaceTop(f=f with{Step=ResolutionFrameStep.ResolvingEffect});
  switch(choice.Parameters["branch"])
  {
   case"yang":case"yin":native.State(f,choice.Parameters["branch"]=="yin");Finish(frames.ActiveProgram(f.Id));return;
   case"actor":frames.ReplaceTop(f=f with{MouXunYuAnniversary=r with{Actor=value}});Adjust(f);return;
   case"add":frames.ReplaceTop(f with{MouXunYuAnniversary=r with{Selected=r.Selected.Append(choice.Cards.Single()).ToArray()}});Continue(f.Id);return;
   case"clear":frames.ReplaceTop(f with{MouXunYuAnniversary=r with{Selected=[]}});Continue(f.Id);return;
   case"done":frames.ReplaceTop(f=f with{MouXunYuAnniversary=r with{Stage=MouXyStage.DiscardChildren,Before=facts.Sequence,After=facts.Sequence},PendingMovementContinuation=new(r.Actor,0,null)});native.Discard(f);Continue(f.Id);return;
   case"kind":frames.ReplaceTop(f with{MouXunYuAnniversary=r with{Kind=(CardKind)value,Stage=MouXyStage.Plan}});Continue(f.Id);return;
   case"plan":var plan=facts.Plans(f).Where(p=>p.Kind==r.Kind).ElementAt(value);frames.ReplaceTop(f=f with{MouXunYuAnniversary=r with{Plan=plan,Stage=r.ActualDiscard>0?MouXyStage.Repeat:MouXyStage.IssuingUse}});if(r.ActualDiscard>0)Publish(f);else native.Use(f);return;
   case"repeat":case"single":frames.ReplaceTop(f=f with{MouXunYuAnniversary=r with{Repeat=choice.Parameters["branch"]=="repeat",Stage=MouXyStage.IssuingUse}});native.Use(f);return;
   case"beneficiary":var grant=new MouXyBizuoGrant(f.Id,r.Source,r.GameplayHash,r.Turn,value);events.AdvanceFact(new MouXyBizuoGrantedEvent(grant));native.Pend(f,grant);Finish(frames.ActiveProgram(f.Id));return;
   case"allocate-card":var card=facts.AllocationCards(f).Single(c=>c.Id==choice.Cards.Single());frames.ReplaceTop(f with{MouXunYuAnniversary=r with{AllocationCard=card}});Continue(f.Id);return;
   case"allocate-recipient":frames.ReplaceTop(f=f with{MouXunYuAnniversary=r with{AllocationRecipient=value,Stage=MouXyStage.AllocationChildren,Before=facts.Sequence,After=facts.Sequence},PendingMovementContinuation=new(value,0,null)});native.Allocate(f);Continue(f.Id);return;
   default:throw new InvalidOperationException("Unknown Mou Xun Yu branch.");
  }
 }
 private void Adjust(ProgramSkillFrame f)
 {
  var r=f.MouXunYuAnniversary!;native.State(f,!r.Yin);var difference=facts.MaximumHp(r.Actor)-facts.HandCount(r.Actor);
  if(difference>0){var requested=Math.Min(5,difference);frames.ReplaceTop(f=f with{MouXunYuAnniversary=r with{Stage=MouXyStage.Drawing,Requested=requested}});draws.BeginOperationProgramDraw(f,r.Actor,requested,new("skill-program.mou:shimou.draw"));return;}
  var discard=Math.Min(Math.Max(0,-difference),facts.Hand(r.Actor).Count);frames.ReplaceTop(f=f with{MouXunYuAnniversary=r with{Requested=discard,Stage=discard>0?MouXyStage.Discard:MouXyStage.Kind}});Continue(f.Id);
 }
 [ProgramNativeDrawReturn(SkillProgramEffectOp.ResolveMouXunYuAnniversaryShimou)]private void DrawReturned(ProgramSkillFrame f,NativeDrawOutcome result){if(!Valid(f)||f.MouXunYuAnniversary is not{Stage:MouXyStage.Drawing,Draw:null}r||result.RecipientSeat!=r.Actor||result.RequestedCount!=r.Requested)throw new InvalidOperationException("Shimou requires its one original actor/amount actual Draw receipt.");frames.Replace(f.Id,f with{MouXunYuAnniversary=r with{Stage=MouXyStage.DrawChildren,Draw=result,ActualDraw=result.ActualDrawIds.Count,Before=result.SequenceBefore,After=result.SequenceAfter},PendingMovementContinuation=new(r.Actor,0,null)});events.AdvanceFact(new MouXyDrawReturnedEvent(f.Id,r.Actor,r.Requested,result.ActualDrawIds.Count,result.ReplacementGainedIds.Count,result.AttemptFrameId));Continue(f.Id);}
 internal void DiscardPaid(long id,IReadOnlyList<CardMovementRecord> moves){var f=frames.ActiveProgram(id);var r=f.MouXunYuAnniversary!;if(!Valid(f)||r.Stage!=MouXyStage.DiscardChildren||moves.Count!=r.Selected.Count||moves.Any(m=>!r.Selected.Contains(m.CardId)||m.From!=CardLocation.Hand(r.Actor)||m.Sequence<=r.Before||m.To!=CardLocation.DiscardPile&&m.To!=CardLocation.OutsideGame))throw new InvalidOperationException("Shimou requires the selected actor's actual logical Hand discard receipt.");frames.Replace(id,f with{MouXunYuAnniversary=r with{ActualDiscard=moves.Count,After=moves.Max(m=>m.Sequence)}});foreach(var m in moves)events.AdvanceFact(new MouXyDiscardPaidEvent(id,r.Actor,m.CardId,m.From,m.To,m.Sequence));}
 internal void AllocationPaid(long id,IReadOnlyList<CardMovementRecord> moves){var f=frames.ActiveProgram(id);var r=f.MouXunYuAnniversary!;if(!Valid(f)||r is not{Stage:MouXyStage.AllocationChildren,Lease:{}g,AllocationCard:{}card}||moves is not[var move]||move.CardId!=card.Id||move.From!=card.From||move.To!=CardLocation.Hand(r.AllocationRecipient)||move.Sequence<=r.Before||facts.History<MouXyAllocatedEvent>().Any(e=>e.GrantFrameId==g.FrameId&&e.CardId==card.Id))throw new InvalidOperationException("Bizuo allocation requires the exact eligible entity's real native movement.");frames.Replace(id,f with{MouXunYuAnniversary=r with{After=move.Sequence}});events.AdvanceFact(new MouXyAllocatedEvent(id,g.FrameId,card.Id,r.AllocationRecipient,move.From,card.SourceSequence,card.ZhifouFrameId,move.Sequence));}
 internal void Bound(ProgramSkillFrame supplied,long use,long action){var f=frames.OfType<ProgramSkillFrame>().SingleOrDefault(f=>f.Id==supplied.Id);if(f is null||f.MouXunYuAnniversary is not{}r||!Valid(f)||r.Stage!=MouXyStage.IssuingUse||r.UseId!=0||r.Plan is null||frames.Top is not CardUseFrame child||child.Id!=use||child.VirtualOrdinaryTrickOrigin?.ParentProgramFrameId!=f.Id||child.Action?.ActionId!=action||child.SourceSeat!=r.Actor)throw new InvalidOperationException("Shimou cannot bind another native use or replace its exact paid ancestor.");frames.Replace(f.Id,f with{MouXunYuAnniversary=r with{Stage=MouXyStage.NativeUse,UseId=use,ActionId=action}});events.AdvanceFact(new MouXyUseIssuedEvent(f.Id,use,action,r.Actor,r.Plan.Kind,r.Plan.Extra,r.Repeat));}
 internal void Returned(long id,long use,long action,bool attack){var f=frames.ActiveProgram(id);var r=f.MouXunYuAnniversary!;if(!Valid(f)||r.Stage!=MouXyStage.NativeUse||r.UseId!=use||r.ActionId!=action||facts.History<MouXyUseReturnedEvent>().Any(e=>e.FrameId==id))throw new InvalidOperationException("Shimou lost its one completed native Use return.");frames.Replace(id,f with{MouXunYuAnniversary=r with{Stage=MouXyStage.ReturnedUse}});events.AdvanceFact(new MouXyUseReturnedEvent(id,use,action));if(!attack)frames.AdvanceProgram(id);}
 internal void Continue(long id){if(frames.Top is not ProgramSkillFrame{MouXunYuAnniversary:{}r}f||f.Id!=id)return;if(!Valid(f))throw new InvalidOperationException("Mou Xun Yu lost his actual paid continuation.");if(r.Stage is MouXyStage.Initial or MouXyStage.Target or MouXyStage.Discard or MouXyStage.Kind or MouXyStage.Plan or MouXyStage.Repeat or MouXyStage.Beneficiary or MouXyStage.Allocation){if(r.Stage==MouXyStage.Allocation&&r.AllocationCard is{}selected&&!facts.AllocationCards(f).Contains(selected))frames.ReplaceTop(f=f with{MouXunYuAnniversary=r with{AllocationCard=null,AllocationRecipient=-1}});Publish(f);return;}if(r.Stage is MouXyStage.Drawing or MouXyStage.IssuingUse or MouXyStage.NativeUse)return;if(native.Drain(f))return;frames.ReplaceTop(f=f with{PendingMovementContinuation=null});if(r.Stage is MouXyStage.DrawChildren or MouXyStage.DiscardChildren){frames.ReplaceTop(f=f with{MouXunYuAnniversary=r with{Stage=MouXyStage.Kind}});Publish(f);return;}if(r.Stage==MouXyStage.AllocationChildren){frames.ReplaceTop(f=f with{MouXunYuAnniversary=r with{Stage=MouXyStage.Allocation,AllocationCard=null,AllocationRecipient=-1}});Publish(f);return;}Finish(f);}
 private void Finish(ProgramSkillFrame f){if(f.MouXunYuAnniversary is{Operation:SkillProgramEffectOp.SettleMouXunYuAnniversaryBizuo,Lease:{}g}){if(facts.History<MouXyAllocationCompletedEvent>().Any(e=>e.GrantFrameId==g.FrameId))throw new InvalidOperationException("Bizuo cannot allocate the same actual extra turn twice.");events.AdvanceFact(new MouXyAllocationCompletedEvent(f.Id,g.FrameId,facts.Turn));}events.AdvanceFact(new MouXyCompletedEvent(f.Id));frames.ReplaceTop(f=f with{MouXunYuAnniversary=null,PendingMovementContinuation=null});native.Finish(f);}
 [ProgramRuleObserver(ProgramRulePhase.BeforeEvent,37200)]private void StartLease(TurnStartedEvent started){if(facts.PendingLease is not{}g||!facts.ExtraTurnStarted(started,g))return;events.AdvanceFact(new MouXyBizuoStartedEvent(g,started.TurnNumber,started.ActorSeat));native.Suppress(g,started.TurnNumber,facts.Living().Where(s=>s!=g.Source.OwnerSeat&&s!=g.Beneficiary).ToArray());}
 [ProgramRuleObserver(ProgramRulePhase.BeforeEvent,37201)]private void EndLease(TurnEndedEvent ended){foreach(var s in facts.History<MouXyBizuoStartedEvent>().Where(s=>s.ActualTurn==ended.TurnNumber&&s.Actor==ended.ActorSeat))events.AdvanceFact(new MouXyBizuoEndedEvent(s.Grant,s.ActualTurn,s.Actor));}
 [ProgramRuleObserver(ProgramRulePhase.AfterEvent,37200)]private void Capture(CardMovedEvent moved){var active=facts.History<MouXyBizuoStartedEvent>().LastOrDefault(s=>s.ActualTurn==facts.Turn&&!facts.History<MouXyBizuoEndedEvent>().Any(e=>e.Grant.FrameId==s.Grant.FrameId));if(active is not null&&facts.NonDiscardEntry(moved,out var card,out var sequence))events.AdvanceFact(new MouXyDiscardEntryRecordedEvent(new(active.Grant.FrameId,facts.Turn,card,sequence)));}
 [ProgramContinuation(ProgramContinuationKind.Resume,37200)]private bool Resume(long id){if(frames.Top is not ProgramSkillFrame{MouXunYuAnniversary:not null}f||f.Id!=id)return false;Continue(id);return true;}
 [ProgramContinuation(ProgramContinuationKind.Movement,37200)]private bool Movement(ProgramSkillFrame f)=>f.MouXunYuAnniversary is not null&&Resume(f.Id);
 [ProgramRuntimeHook(ProgramRuntimePhase.AfterOwnerDeath,37200)][ProgramRuntimeHook(ProgramRuntimePhase.AfterSkillLoss,37200)]private bool Paid(ProgramSkillFrame f)=>f.MouXunYuAnniversary is not null&&Valid(f);
 [ProgramFrameInvariant(ProgramFrameInvariantPhase.AfterSelectionState,37200)]private void Invariant(ProgramSkillFrame f){if(f.MouXunYuAnniversary is not null&&!Valid(f))throw new InvalidOperationException("Invalid own-frame Mou Xun Yu source/payment interval.");}
 [ProgramAiChoice(SkillProgramEffectOp.InitializeMouXunYuAnniversaryShimou,SkillProgramEffectOp.ResolveMouXunYuAnniversaryShimou,SkillProgramEffectOp.ResolveMouXunYuAnniversaryBizuo,SkillProgramEffectOp.SettleMouXunYuAnniversaryBizuo)]private PromptChoice Ai(PendingDecision p,ProgramSkillFrame f)=>p.Choices.FirstOrDefault(c=>c.Parameters.GetValueOrDefault("branch")=="done")??p.Choices.First();
